const api=async(path,opts={})=>{const t=localStorage.getItem("verity_token");const r=await fetch("/api"+path,{...opts,headers:{"Content-Type":"application/json",...(t?{Authorization:"Bearer "+t}:{}),...opts.headers}});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||"Request failed");return d;};
const fmt=v=>v?new Date(v).toLocaleDateString("en-GB",{day:"2-digit",month:"short",year:"numeric"}):"—";
const initials=n=>(n||"V").split(" ").slice(0,2).map(x=>x[0]).join("").toUpperCase();
function Login({done}){const [mode,setMode]=useState("login"),[form,setForm]=useState({fullName:"",email:"",password:"",role:"GRADUATE",institution:"",organizationName:"",organizationType:"INSTITUTION",registrationNumber:"",officialWebsite:"",officialEmailDomain:"",accreditationBody:"",organizationCode:"",studentNumber:""}),[err,setErr]=useState(""),[success,setSuccess]=useState(""),[busy,setBusy]=useState(false);const change=e=>setForm({...form,[e.target.name]:e.target.value});const chooseRole=role=>setForm(v=>({...v,role,organizationType:role==="INSTITUTION_ADMIN"?"INSTITUTION":"EMPLOYER",organizationName:"",registrationNumber:"",officialWebsite:"",officialEmailDomain:"",accreditationBody:""}));async function submit(e){e.preventDefault();setBusy(true);setErr("");setSuccess("");const payload={...form,role:form.role==="GRADUATE"?"GRADUATE":"EMPLOYER",organizationType:form.role==="INSTITUTION_ADMIN"?"INSTITUTION":form.role==="ORGANIZATION_ADMIN"?"EMPLOYER":form.organizationType};try{const d=await api(mode==="login"?"/auth/login":"/auth/register",{method:"POST",body:JSON.stringify(payload)});if(d.pendingEmailConfirmation){setSuccess(d.message||"Check your email to confirm your account.");setMode("login");setForm({...form,password:""});return;}localStorage.setItem("verity_token",d.token);const hydrated=await api("/auth/me").catch(()=>({user:d.user}));done(hydrated.user||d.user);}catch(e){setErr(e.message);}finally{setBusy(false);}}const registration=mode==="register";return <main className="auth"><section className="auth-brand"><div className="brand"><ShieldCheck/><strong>VERITY</strong><span>.</span></div><div><small>BLOCKCHAIN-BASED ACADEMIC CERTIFICATE VERIFICATION SYSTEM</small><h1>Academic credentials, <i>verified with confidence.</i></h1><p>A dedicated workspace for graduates, academic institutions and organizations that need trusted credential verification.</p></div><footer>ACADEMIC CREDENTIAL NETWORK · 2026</footer></section><section className="auth-form"><div className="brand mobile-brand"><ShieldCheck/><strong>VERITY</strong><span>.</span></div><small>BLOCKCHAIN-BASED ACADEMIC CERTIFICATE VERIFICATION SYSTEM</small><h2>{registration?"Choose your Verity workspace":"Sign in to Verity"}</h2><p>{registration?"Each account type has its own registration process, services and workspace.":"Use your registered email and password. Verity opens the workspace assigned to your account."}</p><form onSubmit={submit}>{registration&&<><div className="registration-options"><button type="button" className={"registration-choice "+(form.role==="GRADUATE"?"selected":"")} onClick={()=>chooseRole("GRADUATE")}><GraduationCap/><b>Graduate / Student</b><small>Access personal credentials, join your institution and manage consent for document sharing.</small></button><button type="button" className={"registration-choice "+(form.role==="INSTITUTION_ADMIN"?"selected":"")} onClick={()=>chooseRole("INSTITUTION_ADMIN")}><ShieldCheck/><b>Institution Registration</b><small>For universities, colleges and schools issuing and managing academic certificates.</small></button><button type="button" className={"registration-choice "+(form.role==="ORGANIZATION_ADMIN"?"selected":"")} onClick={()=>chooseRole("ORGANIZATION_ADMIN")}><LockKeyhole/><b>Organization Registration</b><small>For companies, employers and authorized organizations verifying credentials.</small></button></div><label>Full name<input name="fullName" value={form.fullName} onChange={change} required autoComplete="name"/></label>{form.role==="INSTITUTION_ADMIN"&&<div className="registration-detail"><b>Institution administrator application</b><p>Register your institution for certificate issuance, student records, staff permissions and institutional verification. Approval is required before issuing certificates.</p><label>Official institution name<input name="organizationName" value={form.organizationName} onChange={change} required placeholder="University / College / School name"/></label><label>Institution registration number<input name="registrationNumber" value={form.registrationNumber} onChange={change} required placeholder="Official registration identifier"/></label><label>Official website<input name="officialWebsite" type="url" value={form.officialWebsite} onChange={change} required placeholder="https://institution.edu.ng"/></label><label>Official email domain<input name="officialEmailDomain" value={form.officialEmailDomain} onChange={change} placeholder="institution.edu.ng"/></label><label>Accreditation / supervising body<input name="accreditationBody" value={form.accreditationBody} onChange={change} required placeholder="e.g. NUC, NBTE, NCCE or relevant authority"/></label><div className="registration-note">After creating your account, open the Institution Identity Application to upload official registration or accreditation evidence. Verity administrators review the documents before approval.</div></div>}{form.role==="ORGANIZATION_ADMIN"&&<div className="registration-detail organization-detail"><b>Organization verification account</b><p>For employers and other organizations that need to verify graduate credentials. This account does not issue academic certificates.</p><label>Registered organization name<input name="organizationName" value={form.organizationName} onChange={change} required placeholder="Company / organization name"/></label><label>Business registration number (optional)<input name="registrationNumber" value={form.registrationNumber} onChange={change} placeholder="Business registration identifier"/></label><label>Organization website (optional)<input name="officialWebsite" type="url" value={form.officialWebsite} onChange={change} placeholder="https://company.com"/></label><label>Official email domain (optional)<input name="officialEmailDomain" value={form.officialEmailDomain} onChange={change} placeholder="company.com"/></label><div className="registration-note">Your organization account will be reviewed by Verity. Once approved, you can use credential verification and request access to original certificates with graduate consent.</div></div>}{form.role==="GRADUATE"&&<div className="registration-detail"><b>Graduate account</b><p>View your credentials, connect to your institution and control requests to access original certificate documents.</p><label>Institution name (optional)<input name="institution" value={form.institution} onChange={change}/></label><label>Institution registration code (optional)<input name="organizationCode" value={form.organizationCode} onChange={change} placeholder="VRT-1A2B3C4D"/></label><label>Student / matriculation number (optional)<input name="studentNumber" value={form.studentNumber} onChange={change}/></label></div>}</>}<label>Email address<input name="email" type="email" value={form.email} onChange={change} required autoComplete="email"/></label><label>Password<input name="password" type="password" minLength={registration?10:1} value={form.password} onChange={change} required autoComplete={registration?"new-password":"current-password"}/></label>{err&&<div className="error">{err}</div>}{success&&<div className="success">{success}</div>}<button className="primary" disabled={busy}>{busy?"Please wait…":registration?"Create "+(form.role==="INSTITUTION_ADMIN"?"institution":form.role==="ORGANIZATION_ADMIN"?"organization":"graduate")+" account":"Sign in securely"}</button></form><button className="link" onClick={()=>{setMode(registration?"login":"register");setErr("");setSuccess("");}}>{registration?"Already registered? Sign in":"New to Verity? Choose a registration type"}</button><div className="hint"><LockKeyhole size={14}/> Secure authentication · Role-based workspace access</div></section></main>}
function Verify({id,back}){const [data,setData]=useState(null),[busy,setBusy]=useState(true);useEffect(()=>{api("/verify",{method:"POST",body:JSON.stringify({certificateId:id})}).then(setData).catch(e=>setData({verified:false,status:"NOT_FOUND",message:e.message})).finally(()=>setBusy(false));},[id]);return <main className="public"><div className="brand"><ShieldCheck/><strong>VERITY</strong><span>.</span></div><section className="panel"><small>PUBLIC CREDENTIAL CHECK</small><h1>Academic certificate verification</h1><p>Certificate reference: <b>{id}</b></p>{busy?<p>Checking issuer registry…</p>:<Result r={data}/>}<button className="link" onClick={back}>Return to Verity</button></section></main>}
function Result({r}){return <div className={r.verified?"result good":"result bad"}>{r.verified?<CheckCircle2/>:<AlertTriangle/>}<div><b>{r.verified?"Credential verified":r.status==="REVOKED"?"Credential revoked":"Not verified"}</b><p>{r.message}</p>{r.certificate&&<dl><dt>Graduate</dt><dd>{r.certificate.studentName}</dd><dt>Institution</dt><dd>{r.certificate.institution}</dd><dt>Qualification</dt><dd>{r.certificate.qualification}</dd><dt>Award date</dt><dd>{fmt(r.certificate.awardDate)}</dd></dl>}{r.issuer&&<><h4>Registered issuer legal identity</h4><dl><dt>VERITY status</dt><dd>{r.issuer.verificationStatus}</dd><dt>Legal registration number</dt><dd>{r.issuer.registrationNumber||"Not published"}</dd><dt>Official website</dt><dd>{r.issuer.officialWebsite?<a href={r.issuer.officialWebsite} target="_blank" rel="noreferrer">{r.issuer.officialWebsite}</a>:"Not published"}</dd><dt>Official email domain</dt><dd>{r.issuer.officialEmailDomain||"Not published"}</dd><dt>Accreditation body</dt><dd>{r.issuer.accreditationBody||"Not published"}</dd><dt>VERITY approval date</dt><dd>{fmt(r.issuer.verifiedAt)}</dd></dl></>}<small>{r.chain?.enabled?"POLYGON AMOY · ON-CHAIN CHECK":"SUPABASE LEDGER CHECK · OFF-CHAIN"}</small>{r.chain?.enabled&&r.certificate?.txHash&&<p><a href={"https://amoy.polygonscan.com/tx/"+r.certificate.txHash} target="_blank" rel="noreferrer">View blockchain transaction <ExternalLink size={13}/></a></p>}{r.chain?.enabled&&r.chain?.contractAddress&&<p><a href={"https://amoy.polygonscan.com/address/"+r.chain.contractAddress} target="_blank" rel="noreferrer">View smart contract <ExternalLink size={13}/></a></p>}</div></div>}
