const notice=m=>{setToast(m);setTimeout(()=>setToast(""),3000);};
async function doVerify(e){e.preventDefault();setVerified(null);const reference=verifyId.trim();if(!reference)return;try{const endpoint=institutionAdmin?"\/institution\/verify":organizationAdmin&&data?.organization?.type==="EMPLOYER"?"\/organization\/verify":"\/verify";const result=await api(endpoint,{method:"POST",body:JSON.stringify({certificateId:reference,verifierName:user?.fullName,verifierOrg:data?.organization?.name||user?.institution})});setVerified(result);}catch(e){setVerified({verified:false,status:"NOT_FOUND",message:e.message});}}
async function doIssue(e){e.preventDefault();if(organizationAdmin&&!issueFile){setError("Upload the institution-authorized certificate PDF or image before registering this credential.");return;}try{const payload={...issue,institution:organizationAdmin?(data?.organization?.name||issue.institution):issue.institution};const d=await api("/certificates",{method:"POST",body:JSON.stringify(payload)});if(organizationAdmin&&issueFile){try{await api("/certificates/"+d.certificate.certificateId+"/document",{method:"POST",body:issueFile,headers:{"Content-Type":issueFile.type,"X-File-Name":encodeURIComponent(issueFile.name)}});}catch(uploadError){setError("Credential record was created, but its document upload failed: "+uploadError.message);setPage("certificates");await refresh();return;}}notice(d.chainMode==="BLOCKCHAIN"?"Institution-authorized credential issued and recorded on-chain.":"Institution-authorized credential registered in the Supabase certificate ledger.");setIssueFile(null);setIssue({...issue,studentName:"",studentEmail:"",studentNumber:""});setPage("certificates");await refresh();const qrData=await api("/certificates/"+d.certificate.certificateId+"/qr");setQr(qrData);}catch(e){setError(e.message);}}
if(boot)return <div className="loading"><ShieldCheck/> Loading Verity…</div>;if(publicId)return <Verify id={decodeURIComponent(publicId)} back={()=>location.href="/"}/>;if(!user)return <Login done={setUser}/>;const nav=[["overview","Overview",LayoutDashboard],["guidelines","User guidelines",BookOpen],["directory","Registered organizations",Building2],...(admin?[["organizations","Organizations",ShieldCheck],["certificates","All certificates",BadgeCheck],["activity","Audit activity",Activity],["system","System health",CheckCircle2],["settings","Account settings",LockKeyhole]]:graduate&&user.organizationStaff?.length?[...(user.organizationStaff.some(x=>x.status==="ACTIVE"&&x.permissions?.includes("certificates:read"))?[["certificates","Organization credentials",BadgeCheck]]:[]),]:graduate?[["certificates","My credentials",BadgeCheck],["join","Join an institution",Plus],["access","Sharing requests",LockKeyhole],["verify","Verify a credential",CheckCircle2]]:organizationAdmin?[["identity",institutionAdmin?"Institution identity":"Organization identity",ShieldCheck],...(institutionAdmin?[["students","Students / Employees",GraduationCap],["staff","Institution staff",LockKeyhole],["certificates","Certificates",BadgeCheck],["issue","Issue certificate",Plus],["verify","Verify Student Certificates",CheckCircle2]]:[["verify","Verify credentials",CheckCircle2],["access","Verification requests",LockKeyhole]])]:[["verify","Verify credentials",CheckCircle2],["access","Verification requests",LockKeyhole]])];const shown=certs.filter(c=>[c.studentName,c.certificateId,c.institution,c.programme].join(" ").toLowerCase().includes(search.toLowerCase()));
